    @staticmethod
    def _read_webview_local_storage(controller: Any, app_package: str, key: str) -> Mapping[str, Any]:
        pid_output = str(controller.execute_adb(["shell", "pidof", app_package]) or "").strip().split()
        if not pid_output:
            raise RuntimeError(f"OpenFood process is not running: {app_package}")

        port = _free_tcp_port()
        forward_spec = f"tcp:{port}"
        controller.execute_adb(["forward", forward_spec, f"localabstract:webview_devtools_remote_{pid_output[0]}"])
        try:
            with urlopen(f"http://127.0.0.1:{port}/json", timeout=4.0) as response:
                targets = json.loads(response.read().decode("utf-8"))
            target = next(
                (
                    item for item in targets
                    if isinstance(item, Mapping) and str(item.get("webSocketDebuggerUrl") or "").strip()
                ),
                None,
            )
            if target is None:
                raise RuntimeError("OpenFood WebView DevTools target was not found")

            expression = (
                "(function(){"
                f"return window.localStorage.getItem({json.dumps(key)}) || '';"
                "})()"
            )
            raw_value = _devtools_runtime_evaluate(str(target["webSocketDebuggerUrl"]), expression)
        finally:
            controller.execute_adb(["forward", "--remove", forward_spec])

        if not raw_value:
            raise RuntimeError(f"OpenFood localStorage key is missing: {key}")
        parsed = json.loads(raw_value)
        if not isinstance(parsed, Mapping):
            raise RuntimeError(f"OpenFood localStorage {key} must be an object")
        return parsed

